matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define REG_TILE 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int bx = blockIdx.x;  int by = blockIdx.y;
    int tx = threadIdx.x; int ty = threadIdx.y;

    int row_base = by * TILE_SIZE + ty * REG_TILE;
    int col_base = bx * TILE_SIZE + tx * REG_TILE;

    float sum[REG_TILE][REG_TILE] = {0};

    for (int m = 0; m < (N + TILE_SIZE - 1) / TILE_SIZE; m++) {
        // Load tiles into shared memory with coalesced access
        for (int i = 0; i < REG_TILE; i++) {
            for (int j = 0; j < REG_TILE; j++) {
                int row = row_base + i;
                int col = m * TILE_SIZE + tx * REG_TILE + j;
                if (row < N && col < N) {
                    As[ty * REG_TILE + i][tx * REG_TILE + j] = A[row * N + col];
                } else {
                    As[ty * REG_TILE + i][tx * REG_TILE + j] = 0.0f;
                }

                row = m * TILE_SIZE + ty * REG_TILE + i;
                col = col_base + j;
                if (row < N && col < N) {
                    Bs[ty * REG_TILE + i][tx * REG_TILE + j] = B[row * N + col];
                } else {
                    Bs[ty * REG_TILE + i][tx * REG_TILE + j] = 0.0f;
                }
            }
        }

        __syncthreads();

        // Compute using register tiles
        for (int k = 0; k < TILE_SIZE; k++) {
            for (int i = 0; i < REG_TILE; i++) {
                for (int j = 0; j < REG_TILE; j++) {
                    sum[i][j] += As[ty * REG_TILE + i][k] * Bs[k][tx * REG_TILE + j];
                }
            }
        }

        __syncthreads();
    }

    // Write results back
    for (int i = 0; i < REG_TILE; i++) {
        for (int j = 0; j < REG_TILE; j++) {
            int row = row_base + i;
            int col = col_base + j;
            if (row < N && col < N) {
                C[row * N + col] = sum[i][j];
            }
        }
    }
}

