    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    const int TILE_SIZE = 32;
    const int REG_TILE = 4;
    dim3 block_size(TILE_SIZE / REG_TILE, TILE_SIZE / REG_TILE);
    dim3 grid_size((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<grid_size, block_size>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        N
    );

    return C;
}
"""

