import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication with vectorized access and loop unrolling
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define REG_TILE 8

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE + 1];  // +1 to avoid bank conflicts
    __shared__ float Bs[TILE_SIZE][TILE_SIZE + 1];

    int bx = blockIdx.x;  int by = blockIdx.y;
    int tx = threadIdx.x; int ty = threadIdx.y;

    int row_base = by * TILE_SIZE + ty;
    int col_base = bx * TILE_SIZE + tx;

    float sum[REG_TILE] = {0};

    for (int m = 0; m < (N + TILE_SIZE - 1) / TILE_SIZE; m++) {
        // Load tiles into shared memory with vectorized access
        #pragma unroll
        for (int i = 0; i < REG_TILE; i++) {
            int row = row_base;
            int col = m * TILE_SIZE + tx;
            if (row < N && col < N) {
                As[ty][tx] = A[row * N + col];
            } else {
                As[ty][tx] = 0.0f;
            }

            row = m * TILE_SIZE + ty;
            col = col_base;
            if (row < N && col < N) {
                Bs[ty][tx] = B[row * N + col];
            } else {
                Bs[ty][tx] = 0.0f;
            }
        }

        __syncthreads();

        // Compute with loop unrolling
        #pragma unroll 8
        for (int k = 0; k < TILE_SIZE; k++) {
            float a_val = As[ty][k];
            #pragma unroll
            for (int j = 0; j < REG_TILE; j++) {
                if (tx + j * 4 < TILE_SIZE) {
                    sum[j] += a_val * Bs[k][tx + j * 4];
                }
            }
        }

        __syncthreads();
    }

    // Write results back with vectorized stores
    #pragma unroll
    for (int j = 0; j < REG_TILE; j++) {
        int row = row_base;
        int col = col_base + j * 4;
        if (row < N && col < N) {
            C[row * N + col] = sum[j];
        }
    }
}

// Alternative kernel with better memory coalescing
__global__ void matmul_kernel_optimized(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE + 1];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE + 1];

    int bx = blockIdx.x * TILE_SIZE;
    int by = blockIdx.y * TILE_SIZE;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    float sum = 0.0f;

    for (int k = 0; k < N; k += TILE_SIZE) {
        // Coalesced loading
        if (by + ty < N && k + tx < N) {
            As[ty][tx] = A[(by + ty) * N + k + tx];
        } else {
            As[ty][tx] = 0.0f;
        }

        if (k + ty < N && bx + tx < N) {
            Bs[ty][tx] = B[(k + ty) * N + bx + tx];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        #pragma unroll 16
        for (int i = 0; i < TILE_SIZE; i++) {
            sum += As[ty][i] * Bs[i][tx];
        }

        __syncthreads();
    }

    if (by + ty < N && bx + tx < N) {
        C[(by + ty) * N + bx + tx] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    const int TILE_SIZE = 32;
    dim3 block_size(TILE_SIZE, TILE_SIZE);
    dim3 grid_size((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel_optimized<<<grid_size, block_size>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        N
    );

    return C;
}
"""

